UPDATE cs
SET suspendinfo = 0
FROM CustProductStatus cs WITH(UPDLOCK,ROWLOCK)
	INNER JOIN CustInfo ci WITH(NOLOCK) ON ci.custid = cs.custid
WHERE ci.reject = 0 
